const OPTS = ['-h', '--help', '--payload', '--secret'];      // registration order
const TAKES1 = { '--payload': 1, '--secret': 1 };            // '-h'/'--help' take 0
const ACTION_NAME = { '-h': '-h/--help', '--help': '-h/--help',
                      '--payload': '--payload', '--secret': '--secret' };
const NEG = /^-\d+$|^-\d*\.\d+$/u;                           // \d = Unicode Nd

function classify(tok) {                 // -> {kind:'V'} | {kind:'O', opt, expl, sep}
  if (tok === '') return {kind:'V'};
  if (tok[0] !== '-') return {kind:'V'};
  if (OPTS.includes(tok)) return {kind:'O', opt:tok, expl:null, sep:''};
  if (tok.length === 1) return {kind:'V'};                   // bare '-'
  const eq = tok.indexOf('=');
  if (eq !== -1) {
    const head = tok.slice(0, eq), tail = tok.slice(eq + 1);
    if (OPTS.includes(head)) return {kind:'O', opt:head, expl:tail, sep:'='};
  }
  // abbreviation / short-concatenation
  let cands = [];
  if (tok[1] === '-') {                                       // long
    const prefix = eq !== -1 ? tok.slice(0, eq) : tok;
    const expl   = eq !== -1 ? tok.slice(eq + 1) : null;
    for (const o of OPTS) if (o.startsWith(prefix)) cands.push({opt:o, expl, sep: eq!==-1?'=':''});
  } else {                                                    // short
    const short = tok.slice(0, 2), sExpl = tok.slice(2);
    for (const o of OPTS) {
      if (o === short)             cands.push({opt:o, expl:sExpl, sep:''});
      else if (o.startsWith(tok))  cands.push({opt:o, expl:null,  sep:''});
    }
  }
  if (cands.length > 1) fail(`ambiguous option: ${tok} could match ` +
                             cands.map(c=>c.opt).join(', '));
  if (cands.length === 1) return {kind:'O', ...cands[0]};
  if (NEG.test(tok)) return {kind:'V'};                       // no option looks numeric
  if (tok.includes(' ')) return {kind:'V'};                   // U+0020 only
  return {kind:'O', opt:null, expl:null, sep:''};             // unknown option
}

function parse(argv) {                            // argv = process.argv.slice(2)
  // ---- PHASE 1: scan whole argv first ----
  const cls = []; let sawMarker = false;
  for (const tok of argv) {
    if (sawMarker)      { cls.push({kind:'V'}); continue; }
    if (tok === '--')   { sawMarker = true; cls.push({kind:'M'}); continue; }
    cls.push(classify(tok));                      // may fail() with ambiguous
